CREATE POLICY "Authenticated can read questions of active templates"
  ON public.exam_template_questions FOR SELECT TO authenticated
  USING (
    public.has_role(auth.uid(), 'admin'::app_role)
    OR EXISTS (SELECT 1 FROM public.exam_templates t WHERE t.id = template_id AND t.is_active = true)
  )

CREATE POLICY "Authenticated can read questions of active templates"
  ON public.exam_template_questions FOR SELECT TO authenticated
  USING (
    public.is_content_staff(auth.uid())
    OR EXISTS (
      SELECT 1 FROM public.exam_templates t
      WHERE t.id = template_id AND t.is_active = true
    )
  )

CREATE POLICY "Content staff manage import jobs"
  ON public.import_jobs FOR ALL TO authenticated
  USING (public.is_content_staff(auth.uid()))
  WITH CHECK (
    public.is_content_staff(auth.uid())
    AND (
      public.is_full_admin(auth.uid())
      OR import_type <> 'config'
    )
  )
